// table ShipConfig — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct ShipConfig {
    char name[64 + 1] = {}; // string(64): max length, used length beside it
    int32_t name_length = 0;
    int32_t health = 0;
};

// table Item — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct Item {
    int32_t count = 0;
};

// table FleetShipsEntry — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct FleetShipsEntry {
    char key[32 + 1] = {}; // string(32): max length, used length beside it
    int32_t key_length = 0;
    ShipConfig value;
};

// table FleetByIdEntry — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct FleetByIdEntry {
    uint32_t key = 0;
    TableRef value; // *ShipConfig — null until assigned
};

// table FleetLoadoutsEntryValueEntry — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct FleetLoadoutsEntryValueEntry {
    uint8_t key = 0;
    Item value;
};

// table FleetLoadoutsEntry — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct FleetLoadoutsEntry {
    char key[16 + 1] = {}; // string(16): max length, used length beside it
    int32_t key_length = 0;
    TableMap<FleetLoadoutsEntryValueEntry> value; // map[uint8]Item — the sorted entry array, empty until an insert
};

// table FleetTiersEntry — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct FleetTiersEntry {
    int16_t key = 0;
    Item value;
};

// table Fleet — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct Fleet {
    TableMap<FleetShipsEntry> ships; // map[string(32)]ShipConfig — the sorted entry array, empty until an insert
    TableMap<FleetByIdEntry> by_id; // map[uint32]*ShipConfig — the sorted entry array, empty until an insert
    TableRef flagship; // *ShipConfig — null until assigned
    TableMap<FleetLoadoutsEntry> loadouts; // map[string(16)]map[uint8]Item — the sorted entry array, empty until an insert
    TableMap<FleetTiersEntry> tiers; // map[int16]Item — the sorted entry array, empty until an insert
};

// ---- prefill: the declared defaults, in place (docs/SPEC-TABLES.md) ----

inline void ShipConfigReset( ShipConfig & value );
inline void ItemReset( Item & value );
inline void FleetShipsEntryReset( FleetShipsEntry & value );
inline void FleetByIdEntryReset( FleetByIdEntry & value );
inline void FleetLoadoutsEntryValueEntryReset( FleetLoadoutsEntryValueEntry & value );
inline void FleetLoadoutsEntryReset( FleetLoadoutsEntry & value );
inline void FleetTiersEntryReset( FleetTiersEntry & value );
inline void FleetReset( Fleet & value );

inline void ShipConfigReset( ShipConfig & value )
{
    memset( value.name, 0, sizeof( value.name ) );
    value.name_length = 0;
    value.health = 0;
}

inline void ItemReset( Item & value )
{
    value.count = 0;
}

inline void FleetShipsEntryReset( FleetShipsEntry & value )
{
    memset( value.key, 0, sizeof( value.key ) );
    value.key_length = 0;
    ShipConfigReset( value.value );
}

inline void FleetByIdEntryReset( FleetByIdEntry & value )
{
    value.key = 0;
    value.value.value = 0; // *ShipConfig — null
}

inline void FleetLoadoutsEntryValueEntryReset( FleetLoadoutsEntryValueEntry & value )
{
    value.key = 0;
    ItemReset( value.value );
}

inline void FleetLoadoutsEntryReset( FleetLoadoutsEntry & value )
{
    memset( value.key, 0, sizeof( value.key ) );
    value.key_length = 0;
    value.value.entries.value = 0; // map[uint8]Item: empty
    value.value.count = 0;
    value.value.padding = 0;
}

inline void FleetTiersEntryReset( FleetTiersEntry & value )
{
    value.key = 0;
    ItemReset( value.value );
}

inline void FleetReset( Fleet & value )
{
    value.ships.entries.value = 0; // map[string(32)]ShipConfig: empty
    value.ships.count = 0;
    value.ships.padding = 0;
    value.by_id.entries.value = 0; // map[uint32]*ShipConfig: empty
    value.by_id.count = 0;
    value.by_id.padding = 0;
    value.flagship.value = 0; // *ShipConfig — null
    value.loadouts.entries.value = 0; // map[string(16)]map[uint8]Item: empty
    value.loadouts.count = 0;
    value.loadouts.padding = 0;
    value.tiers.entries.value = 0; // map[int16]Item: empty
    value.tiers.count = 0;
    value.tiers.padding = 0;
}

// ---- the arena's reset hook (docs/SPEC-TABLES.md §6) ----
//
// TableWorker::Alloc is a template and cannot name a member's Reset, so
// the arena reaches it through this overload set by argument-dependent
// lookup. It is how a node born in raw arena storage comes to hold the
// declared defaults without value-initialising the whole aggregate.

inline void TableReset( ShipConfig & value ) { ShipConfigReset( value ); }
inline void TableReset( Item & value ) { ItemReset( value ); }
inline void TableReset( FleetShipsEntry & value ) { FleetShipsEntryReset( value ); }
inline void TableReset( FleetByIdEntry & value ) { FleetByIdEntryReset( value ); }
inline void TableReset( FleetLoadoutsEntryValueEntry & value ) { FleetLoadoutsEntryValueEntryReset( value ); }
inline void TableReset( FleetLoadoutsEntry & value ) { FleetLoadoutsEntryReset( value ); }
inline void TableReset( FleetTiersEntry & value ) { FleetTiersEntryReset( value ); }
inline void TableReset( Fleet & value ) { FleetReset( value ); }

// ---- pointer targets: allocation and resolution (docs/SPEC-TABLES.md §2) ----
//
// A reference resolves differently in the two forms, and the CONTEXT says
// which: in the arena it is an offset; in a region it is a self-relative
// delta, so the const deref below is one add and needs no base pointer.

// ShipConfig is a pointer target.
inline const ShipConfig * ShipConfigAt( const TableRef & ref ) // the const form's hot path: one add, no base
{
    return ref.value != 0 ? (const ShipConfig *) ( (const uint8_t *) &ref + ref.value ) : NULL;
}
inline ShipConfig * ShipConfigAt( TableRef & ref )
{
    return ref.value != 0 ? (ShipConfig *) ( (uint8_t *) &ref + ref.value ) : NULL;
}
inline const ShipConfig * ShipConfigAt( const TableRegionCtx &, const TableRef & ref ) { return ShipConfigAt( ref ); }
inline const ShipConfig * ShipConfigAt( const TableArenaCtx & ctx, const TableRef & ref )
{
    return ref.value != 0 ? (const ShipConfig *) TableArenaAt( *ctx.arena, (uint32_t) ref.value ) : NULL;
}
// while the builder is mutable, resolve against the arena itself
inline ShipConfig * ShipConfigAt( TableArena & arena, const TableRef & ref )
{
    return ref.value != 0 ? (ShipConfig *) TableArenaAt( arena, (uint32_t) ref.value ) : NULL;
}
inline const ShipConfig * ShipConfigAt( const TableArena & arena, const TableRef & ref )
{
    return ref.value != 0 ? (const ShipConfig *) TableArenaAt( arena, (uint32_t) ref.value ) : NULL;
}
// allocate one ShipConfig in the arena; the slot holds the arena offset
inline ShipConfig * ShipConfigEmplace( TableWorker & worker, TableRef & slot )
{
    TableSlot<ShipConfig> allocated = worker.Alloc<ShipConfig>();
    slot = allocated.ref;
    return allocated.ptr;
}

